css:
.print-format table,
.print-format tr,
.print-format td,
.print-format div,
.print-format p {
    font-family: Tahoma, sans-serif;
    line-height: 100%;
    vertical-align: middle;

}

.print-format td,
.print-format th {
    padding: 4px !important;
    font-size: 11px;
}

@media screen {
    .print-format {
        padding: 0.25in;
    }
}

.print-format {
    min-height: 0px;
}

.qr-label {
    width: 6cm;
    height: 4cm;
    padding: 6px;
    border: 1px solid #999;
    font-size: 9pt;
    font-family: Arial, sans-serif;
    margin: 4px;
    box-sizing: border-box;
    text-align: center;
}

.table-bordered {
    border-collapse: collapse;
    width: 100%;
}

.table-bordered th,
.table-bordered td {
    border: 1px solid #000 !important;
    text-align: center;
    height: 24px;
    font-weight: bold;
    color: black;
    font-size:17px
}

.header-table td {
    vertical-align: top;
}
